-- Câu mới soạn cho 26 dạng LÝ THUYẾT/HIỆN TƯỢNG có dưới 3 câu chắc (docs/dang-thieu-cau.md), 95 câu.
-- Nguồn: scripts/data/soan-cau-dang-thieu/cau.py (soạn trong phiên 05/11/2026, kiem-code soát độc lập, thầy duyệt qua duyet.html).
-- CHẠY SAU KHI THẦY DUYỆT, sau 22h. Ghi: question_bank (note = 'soan-dang-thieu-ly-thuyet-20261105', archived = false) + question_dang (source = 'claude-2026-11-05-soan-dang-thieu', unsure = false).
-- Câu trùng content_hash với câu đã có thì bỏ qua (không gán dạng cho câu cũ).
-- Rollback (không có bảng nào khác tham chiếu câu mới ngay sau khi nạp):
--   begin; delete from public.question_dang where source = 'claude-2026-11-05-soan-dang-thieu';
--          delete from public.question_bank where note = 'soan-dang-thieu-ly-thuyet-20261105'; commit;
begin;
create temp table _v (q jsonb, tid bigint, tname text, lid bigint, label text) on commit drop;

create temp table _moi on commit drop as
with ins as (
  select 'vat-ly', (select t.grade from public.question_topics t where t.id = v.tid), v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai',
         v.q, public.question_content_hash(v.q), false, 'soan-dang-thieu-ly-thuyet-20261105'
  from _v v
  where not exists (select 1 from public.question_bank b where b.content_hash = public.question_content_hash(v.q))
  returning id, content_hash
)
select ins.id, v.lid, v.label from ins join _v v on public.question_content_hash(v.q) = ins.content_hash;

select id, lid, label, false, 'claude-2026-11-05-soan-dang-thieu' from _moi
on conflict (question_id, lesson_id) do nothing;

-- Kiểm: số câu mới / số gán dạng (kỳ vọng 95 / 95); câu thiếu grade (topic không có lớp) phải = 0
select (select count(*) from public.question_bank where note = 'soan-dang-thieu-ly-thuyet-20261105') as cau_moi,
       (select count(*) from public.question_dang where source = 'claude-2026-11-05-soan-dang-thieu') as gan_dang,
       (select count(*) from public.question_bank where note = 'soan-dang-thieu-ly-thuyet-20261105' and grade is null) as thieu_grade;
commit;
